import{_ as s,o as t,c as e,a2 as l}from"./chunks/framework.a6FUKr6c.js";const v=JSON.parse('{"title":"个人思考","description":"Nana 的数字自留地 · 随想与长文复盘","frontmatter":{"layout":"page","title":"个人思考","description":"Nana 的数字自留地 · 随想与长文复盘"},"headers":[],"relativePath":"thoughts.md","filePath":"thoughts.md"}'),b={name:"thoughts.md"};function d(i,a,c,r,n,o){return t(),e("div",null,[...a[0]||(a[0]=[l('<div class="thoughts-stream-page"><div class="thoughts-header-banner"><div class="th-header-top"><div class="th-header-stamp"><span>🍃</span><span>NANA&#39;S STREAM · 思考自留地</span></div><div class="th-header-stats"><span>🌱 持续随笔记录中</span></div></div><h1 class="th-header-title">灵感碎碎念 &amp; 深度复盘</h1><p class="th-header-desc"> “日常踩坑随时吐槽，长线复盘沉淀认知。” 这里是我的私人记事板，记录零散的认知碎片与学习随笔，也存放严肃的产品设计复盘。 </p></div><div class="stream-list"><div class="thought-bubble-card"><div class="bubble-header"><div class="bubble-avatar">🦊</div><div class="bubble-meta"><div class="bubble-author-row"><span class="bubble-author">Nana Gu</span><span class="bubble-handle">@nana · 备考手记</span></div><span class="bubble-topic-tag">#雅思备考碎碎念</span></div></div><div class="bubble-body"> 最近备考雅思口语 Part 3，猛然发现这玩意儿本质上就是一场<strong>残酷的高压需求评审会</strong>：<br> 考官抛出一个宏观抽象的社会议题（需求），你必须在 3 秒内给出总分总观点、论证逻辑，并补充具体边缘案例（边界条件）。千万别想着背模板套话，就像在技术评审会上背八股文一样，考官一眼就能识破你的假大空。真诚而有逻辑的表达，才是最高效的沟通。 </div><div class="bubble-footer"><span class="bubble-action">🌱 日常随笔</span><span class="bubble-action">☕ 备考中</span><span class="bubble-action">📍 北京</span></div></div><article class="thought-article-card"><div class="article-top-row"><div class="article-badge-group"><span class="art-badge badge-saas">SaaS 架构设计</span><span class="art-badge badge-growth">状态机模型</span></div><span class="article-date-meta">深度长文 · 架构沉淀</span></div><h2 class="art-title">SaaS 产品的逆向流转：为什么“售后与回收”比正向销售更难做？</h2><div class="art-quote"> 💡 <strong>核心设计洞察</strong>：正向销售是“基于确定性承诺的履约”，而逆向售后是“基于不确定性博弈的仲裁”。谁能把非标品的质检状态机抽象干净，谁就能掌握二手供应链的定价主动权。 </div><div class="art-summary"> 在负责某 3C 零售集团的售后回收平台 0→1 重构时，我们踩穿了内部 5 套孤岛系统的所有坑。本文系统梳理设备生命周期中的“多阶段状态机跃迁（FSM）”、加盟门店数据物理隔离，以及如何将原本线下的纸质权益卡全面数字化并搭建防羊毛风控防线。 </div><div class="article-card-footer"><div class="article-metrics"><span>📐 架构复盘</span><span>📦 B端中台</span></div><a href="/projects#project-01" class="read-full-btn"> 👉 阅读项目复盘 </a></div></article><div class="thought-bubble-card"><div class="bubble-header"><div class="bubble-avatar">🤖</div><div class="bubble-meta"><div class="bubble-author-row"><span class="bubble-author">Nana Gu</span><span class="bubble-handle">@nana · 行业吐槽</span></div><span class="bubble-topic-tag">#AI杂谈吐槽</span></div></div><div class="bubble-body"> 今天和做业务的同事聊 AI 落地，发现大家最大的执念依然是<strong>“企图用更大的模型来掩盖产品设计的懒惰”</strong>。<br> 知识库搜不准？换更大参数！回答有幻觉？加更长的提示词！<br> 然而事实上一旦深入业务现场就会发现：90% 的问答翻车源自于最基础的分块策略粗糙、元数据过滤失效，以及业务端根本没有统一的术语词典。算法不是万灵丹，懂业务逻辑、做好脏活累活的 PM 才是大模型落地的稳定器。 </div><div class="bubble-footer"><span class="bubble-action">🌱 认知迭代</span><span class="bubble-action">🎯 业务第一性原理</span></div></div><article class="thought-article-card"><div class="article-top-row"><div class="article-badge-group"><span class="art-badge badge-ai">大模型落地</span><span class="art-badge badge-saas">RAG 实践</span></div><span class="article-date-meta">实战总结 · 避坑指南</span></div><h2 class="art-title">当 LLM 遇上 B 端业务：我总结的 5 个“不能照搬 C 端”的惨痛教训</h2><div class="art-quote"> 💡 <strong>核心设计洞察</strong>：C 端用户对 AI 的容错率是“哈哈真幽默”，B 端客户对 AI 的容错率是“算错一分钱直接发律师函拒付尾款”。 </div><div class="art-summary"> 本文系统复盘内部知识问答 Agent 从 POC 验证到千人规模化落地的真实经历。从权限穿透拦截、多轮上下文滑动窗口控制、结构化 CoT 推理打分，到建立“评分幻觉拦截兜底机制”，带你避开大模型进 B 端必踩的深坑。 </div><div class="article-card-footer"><div class="article-metrics"><span>🤖 Agent设计</span><span>🛡️ 真实场景落地</span></div><a href="/projects#project-02" class="read-full-btn"> 👉 阅读项目复盘 </a></div></article><div class="thought-bubble-card"><div class="bubble-header"><div class="bubble-avatar">💻</div><div class="bubble-meta"><div class="bubble-author-row"><span class="bubble-author">Nana Gu</span><span class="bubble-handle">@nana · 造物手记</span></div><span class="bubble-topic-tag">#造物手记</span></div></div><div class="bubble-body"> 写游乐园管理系统全栈代码的最大收获，不是学会了怎么用 Flask 调 Redis，而是<strong>彻底治好了我之前提需求时“想当然”的毛病</strong>。<br> 当我自己在 Pinia store 里面为“退票和取消预约”的状态同步抓狂时，我瞬间理解了前端同事看到我原来那版 PRD 时的杀气从何而来……产品逻辑顺畅的代码写起来行云流水；代码写得极其痛苦，必然是原型逻辑一开始就定义错了！ </div><div class="bubble-footer"><span class="bubble-action">🛠️ 顿悟时刻</span><span class="bubble-action">🌿 持续写代码中</span></div></div></div></div>',1)])])}const u=s(b,[["render",d]]);export{v as __pageData,u as default};
